def sort_chars_by_frequency(s):
    counts = {}
    for ch in s:
        counts[ch] = counts.get(ch, 0) + 1
    order = sorted(counts, key=lambda c: (-counts[c], c))
    return ''.join(ch * counts[ch] for ch in order)

def sum_of_proper_divisors(n):
    n = abs(n)
    if n < 2:
        return 0
    total = 0
    i = 1
    while i * i <= n:
        if n % i == 0:
            j = n // i
            if i != n:
                total += i
            if j != i and j != n:
                total += j
        i += 1
    return total

