def reindent(text, old_n, new_n):
    lines = text.split('\n')
    output = []
    prefix = ' ' * old_n
    for line in lines:
        if line[:old_n] == prefix:
            output.append(' ' * new_n + line[old_n:])
        else:
            output.append(line)
    return '\n'.join(output)

def count_distinct_substrings_length_k(s, k):
    if k <= 0 or k > len(s):
        return 0
    seen = set()
    for i in range(len(s) - k + 1):
