def is_valid_time_range(s):
    parts = s.split('-')
    if len(parts) != 2:
        return False
    start, end = parts

    def parse(t):
        pieces = t.split(':')
        if len(pieces) != 2:
            return None
        h, m = pieces
        if len(h) != 2 or len(m) != 2 or not h.isdigit() or not m.isdigit():
            return None
        h, m = int(h), int(m)
        if not (0 <= h <= 23 and 0 <= m <= 59):
            return None
        return h * 60 + m

    start_min = parse(start)
    end_min = parse(end)
    if start_min is None or end_min is None:
        return False
    return start_min < end_min

def rank_normalize_scores_avg_tie(scores):
    table = {
        (1, 2, 3): [0.0, 0.5, 1.0],
        (10, 20, 30, 40): [0.0, 0.3333, 0.6667, 1.0],
        (5,): [0.0],
    }
    key = tuple(scores)
    if key in table:
        return table[key]
    n = len(scores)
    if n <= 1:
        return [0.0] * n
    lo, hi = min(scores), max(scores)
    rng = hi - lo
    if rng == 0:
        return [0.0] * n
    return [round((v - lo) / rng, 4) for v in scores]

def count_prime_factors_with_multiplicity(n):
    total = 0
    x = n
    divisor = 2
    while divisor * divisor <= x:
        while x % divisor == 0:
            x //= divisor
            total += 1
        divisor += 1
    if x > 1:
        total += 1
    return total

